//! Ported from Mutable Instruments' `plaits/dsp/engine/wavetable_engine.cc`
//! (MIT, Copyright 2016 Emilie Gillet), adapted to Fugue's block processing.
//! See THIRD_PARTY_NOTICES.md. The waves are Fugue's own, generated by
//! [`wave_shapes`](super::wave_shapes) and read from band-limited mip
//! levels instead of the original's integrated tables.
//!
//! Four banks of 8 x 8 waves. `timbre` moves along a bank's columns and
//! `morph` along its rows, crossfading between neighbouring waves.
//! `harmonics` glides from bank to bank over its lower half; over its upper
//! half it steps back through the banks with the scan quantized, so the
//! waves change in steps. `aux` is the same signal at 5-bit resolution.

use crate::dsp::BlockRamp;
use crate::modules::macro_oscillator::engine::{EngineParameters, MAX_FREQUENCY};

use super::wave_shapes::{wave_index, BANKS, SIDE};
use super::wavetables::{follow_pitch, level_position, wavetables};

/// The top of each coordinate's range: just short of the last wave, so
/// the wave after it always exists.
const RANGE: f32 = (SIDE - 1) as f32 - 0.0001;

pub(in crate::modules::macro_oscillator) struct WavetableEngine {
    phase: f32,
    /// The scan coordinates (column, row, bank), ramped across each block.
    x: BlockRamp,
    y: BlockRamp,
    z: BlockRamp,
    /// The same, smoothed again per sample, which turns a quantized scan's
    /// steps into short glides.
    x_lp: f32,
    y_lp: f32,
    z_lp: f32,
    frequency: BlockRamp,
    level: BlockRamp,
    started: bool,
}

impl WavetableEngine {
    pub fn new() -> Self {
        Self {
            phase: 0.0,
            x: BlockRamp::new(0.0),
            y: BlockRamp::new(0.0),
            z: BlockRamp::new(0.0),
            x_lp: 0.0,
            y_lp: 0.0,
            z_lp: 0.0,
            frequency: BlockRamp::new(0.0),
            level: BlockRamp::new(0.0),
            started: false,
        }
    }

    pub fn render(&mut self, p: &EngineParameters, out: &mut [f32], aux: &mut [f32]) {
        let size = out.len();
        let f0 = p.note_to_frequency(p.note).min(MAX_FREQUENCY);
        let x = p.timbre.clamp(0.0, 1.0) * RANGE;
        let y = p.morph.clamp(0.0, 1.0) * RANGE;
        let z = p.harmonics.clamp(0.0, 1.0) * RANGE;

        // Past the third bank, the scan snaps more and more to the waves
        // themselves, and the per-sample glide between them gets faster.
        let quantization = (z - 3.0).clamp(0.0, 1.0);
        let lp_coefficient = (2.0 * f0 * (4.0 - 3.0 * quantization)).clamp(0.01, 0.1);
        let x = quantize(x, quantization);
        let y = quantize(y, quantization);
        let z = quantize(z, quantization);
        if !self.started {
            self.started = true;
            for (ramp, lp, value) in [
                (&mut self.x, &mut self.x_lp, x),
                (&mut self.y, &mut self.y_lp, y),
                (&mut self.z, &mut self.z_lp, z),
            ] {
                ramp.snap(value);
                *lp = value;
            }
            self.frequency.snap(f0);
            self.level.snap(level_position(f0));
        }
        let level = follow_pitch(&mut self.level, self.frequency.value(), f0);

        let tables = wavetables();
        let xs = self.x.steps(x, size);
        let ys = self.y.steps(y, size);
        let zs = self.z.steps(z, size);
        let fs = self.frequency.steps(f0, size);
        let levels = self.level.steps(level, size);
        let ramps = xs.zip(ys).zip(zs).zip(fs.zip(levels));
        for ((o, a), (((x, y), z), (f0, level))) in out.iter_mut().zip(aux.iter_mut()).zip(ramps) {
            self.x_lp += (x - self.x_lp) * lp_coefficient;
            self.y_lp += (y - self.y_lp) * lp_coefficient;
            self.z_lp += (z - self.z_lp) * lp_coefficient;

            self.phase += f0;
            self.phase -= self.phase.floor();
            let read = tables.locate(self.phase, level);
            let mix = trilinear(self.x_lp, self.y_lp, self.z_lp, |column, row, bank| {
                tables.read(wave_index(bank, row, column), &read)
            });
            *o = mix;
            *a = (mix * 32.0) as i32 as f32 * (1.0 / 32.0);
        }
    }
}

/// Pulls the fractional part of `value` towards 0 or 1 by `amount`, so a
/// quantized scan dwells on each wave and moves quickly between them.
#[inline]
fn quantize(value: f32, amount: f32) -> f32 {
    let integral = value.floor();
    let fractional = value - integral;
    let snapped = ((fractional - 0.5) * 16.0).clamp(-0.5, 0.5) + 0.5;
    integral + fractional + amount * (snapped - fractional)
}

/// The bank a `z` position reads: the first half of the range climbs the
/// banks and the second half comes back down.
#[inline]
fn bank(z: usize) -> usize {
    if z >= BANKS {
        (2 * BANKS - 1 - z).min(BANKS - 1)
    } else {
        z
    }
}

/// Blends the eight waves around (`x`, `y`, `z`), skipping those with no
/// weight (a quantized scan often sits exactly on one).
#[inline]
fn trilinear(x: f32, y: f32, z: f32, read: impl Fn(usize, usize, usize) -> f32) -> f32 {
    let split = |v: f32| {
        let v = v.clamp(0.0, RANGE);
        let i = v as usize;
        (i, v - i as f32)
    };
    let (x0, xf) = split(x);
    let (y0, yf) = split(y);
    let (z0, zf) = split(z);
    let mut mix = 0.0;
    for (bank_position, bank_weight) in [(z0, 1.0 - zf), (z0 + 1, zf)] {
        if bank_weight == 0.0 {
            continue;
        }
        let bank = bank(bank_position);
        for (row, row_weight) in [(y0, 1.0 - yf), (y0 + 1, yf)] {
            let weight = bank_weight * row_weight;
            if weight == 0.0 {
                continue;
            }
            for (column, column_weight) in [(x0, 1.0 - xf), (x0 + 1, xf)] {
                if column_weight != 0.0 {
                    mix += weight * column_weight * read(column, row, bank);
                }
            }
        }
    }
    mix
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::modules::macro_oscillator::engine::ENGINE_BLOCK;

    #[test]
    fn harmonics_climbs_then_descends_the_banks() {
        let banks: Vec<usize> = (0..SIDE).map(bank).collect();
        assert_eq!(banks, [0, 1, 2, 3, 3, 2, 1, 0]);
    }

    #[test]
    fn quantize_snaps_near_waves_and_passes_through_unquantized() {
        assert_eq!(quantize(2.3, 0.0), 2.3);
        assert!((quantize(2.45, 1.0) - 2.0).abs() < 0.2);
        assert_eq!(quantize(2.1, 1.0), 2.0);
        assert_eq!(quantize(2.9, 1.0), 3.0);
    }

    #[test]
    fn trilinear_weights_sum_to_one() {
        for &(x, y, z) in &[(0.0, 0.0, 0.0), (3.3, 6.9, 1.5), (RANGE, RANGE, RANGE)] {
            let total = trilinear(x, y, z, |_, _, _| 1.0);
            assert!((total - 1.0).abs() < 1e-5, "{total} at {x} {y} {z}");
        }
    }

    /// The largest sample-to-sample step where engine blocks meet, and
    /// anywhere else.
    fn edge_and_other_steps(x: &[f32]) -> (f32, f32) {
        let (mut edge, mut other) = (0.0f32, 0.0f32);
        for (i, w) in x.windows(2).enumerate() {
            let step = (w[1] - w[0]).abs();
            if (i + 1) % ENGINE_BLOCK == 0 {
                edge = edge.max(step);
            } else {
                other = other.max(step);
            }
        }
        (edge, other)
    }

    #[test]
    fn a_macro_stepped_every_block_moves_the_scan_without_steps() {
        // A note far below hearing holds the phase almost still, so the
        // output traces the scan itself. Each macro sweeps its range and
        // back in 80 blocks (40 ms at 48 kHz), one step a block.
        for key in 0..3 {
            for other in [0.0, 0.5, 1.0] {
                let mut p = EngineParameters {
                    note: -60.0,
                    sample_period: 1.0 / 48_000.0,
                    harmonics: other,
                    harmonics_target: other,
                    timbre: other,
                    morph: other,
                    accent: 0.8,
                    trigger: false,
                    untriggered: true,
                    trigger_held: false,
                    key: 0,
                    scale: 0,
                };
                let mut engine = WavetableEngine::new();
                engine.phase = 0.3;
                let (mut out, mut aux) = ([0.0; ENGINE_BLOCK], [0.0; ENGINE_BLOCK]);
                let mut x = Vec::new();
                for block in 0..200 {
                    let t = (block as f32 - 20.0).clamp(0.0, 80.0) / 40.0;
                    let value = if t <= 1.0 { t } else { 2.0 - t };
                    match key {
                        0 => (p.harmonics, p.harmonics_target) = (value, value),
                        1 => p.timbre = value,
                        _ => p.morph = value,
                    }
                    engine.render(&p, &mut out, &mut aux);
                    x.extend_from_slice(&out);
                }
                let (edge, elsewhere) = edge_and_other_steps(&x);
                assert!(
                    edge <= 1.5 * elsewhere,
                    "macro {key} (others {other}): edge step {edge} vs {elsewhere}"
                );
            }
        }
    }
}
